20	    private DailyOwnerRegistrations() {
21	    }
22	
23	    /** Number of owners registered on the current business day. */
24	    static int countToday(OwnerRepository ownerRepository) {
25	        LocalDate today = BusinessDay.rollForward(LocalDate.now());
26	        int count = 0;
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (today.equals(existing.getRegistrationDate())) {
